import json
translations = {
  "1580": "નવસારીએ અગ્રણી ઉદ્યોગપતિઓ (ટાટા કુટુંબનો વંશ) ઉછેરીને અને દાંડી કૂચ માટે કેન્દ્રબિંદુ તરીકે સેવા આપીને ભારતના નાગરિક અને સાંસ્કૃતિક માળખાને ઊંડાણપૂર્વક આકાર આપ્યો છે, જેણે ભારતીય સ્વતંત્રતા માટે વૈશ્વિક સમર્થનને વેગ આપ્યો હતો.",
  "1584": "નવસારી પૂર્ણા નદીના ચક્રીય પૂર સામે સમુદાય-આગેવાની હેઠળની આપત્તિ સજ્જતા અને અદ્યતન કૃષિ વિસ્તરણ કાર્યક્રમો દ્વારા દરિયાકાંઠાની જમીનની ખારાશનો સામનો કરવા માટે વ્યૂહાત્મક પગલાં દ્વારા સ્થિતિસ્થાપકતા દર્શાવે છે.",
  "1595": "સ્વદેશી રાઠવા અને ભીલ સમુદાયો જિલ્લાની જીવંત સંસ્કૃતિને વ્યાખ્યાયિત કરે છે, જે જીવંત મેળાઓ, પરંપરાગત પિઠોરા ચિત્રો અને લોકનૃત્યો દ્વારા પ્રદર્શિત થાય છે. પાવાગઢ એક મુખ્ય તીર્થધામ છે, જે નવરાત્રિ દરમિયાન લાખો લોકોને આકર્ષે છે.",
  "1600": "અસમાન ભૂપ્રદેશ, જંગલવાળી ટેકરીઓ અને કૃષિ મેદાનો દ્વારા વર્ગીકૃત થયેલ છે. વિશ્વામિત્રી નદી પાવાગઢની ટેકરીઓમાંથી ઉદ્ભવે છે. પર્યાવરણીય પડકારોમાં જંગલોની કાપણી, જમીનનું ધોવાણ અને ટકાઉ ભૂગર્ભજળ વ્યવસ્થાપનનો સમાવેશ થાય છે.",
  "1604": "રાણી કી વાવ ·",
  "1610": "સોલંકી વંશની ઐતિહાસિક રાજધાની, પાટણ એ ગુજરાતના શાસ્ત્રીય સ્થાપત્ય અને વિદ્વતાપૂર્ણ કાર્યોના સુવર્ણ યુગનું પ્રમાણપત્ર છે, જે તેના જટિલ પટોળા રેશમ વણાટ માટે વૈશ્વિક સ્તરે પ્રખ્યાત છે.",
  "1614": "અર્થતંત્ર કૃષિ (કપાસ, એરંડા, જીરું), પરંપરાગત હસ્તકલા અને વધુને વધુ, નવીનીકરણીય ઉર્જા પર આધાર રાખે છે. ચારણકા સોલર પાર્ક એશિયાના સૌથી મોટા સૌર ઉર્જા સ્થાપનોમાંનું એક છે, જે આધુનિક આર્થિક પરિવર્તનને આગળ ધપાવે છે.",
  "1618": "વિકાસ પ્રોજેક્ટ્સ મોટા પાયે સૌર ઉર્જા ઈન્ફ્રાસ્ટ્રક્ચર, સુજલામ સુફલામ યોજના દ્વારા જળ સંરક્ષણ અને ગ્રામીણ અંતરિયાળ વિસ્તારો માટે આધુનિક શૈક્ષણિક અને આરોગ્યસંભાળ સુવિધાઓના નિર્માણ પર ધ્યાન કેન્દ્રિત કરે છે.",
  "1642": "મુખ્ય વારસો સ્થળોમાં કીર્તિ મંદિર (ગાંધીજીનું પૈતૃક ઘર) અને કૃષ્ણ અને સુદામાની મિત્રતાની ઉજવણી કરતું સુદામા મંદિરનો સમાવેશ થાય છે. આ જિલ્લામાં નજીકના સ્થળોએ પ્રાચીન હડપ્પન દરિયાઇ વેપારના અવશેષો પણ છે.",
  "1646": "પોરબંદરે વિશ્વને મહાત્મા ગાંધી ભેટ આપ્યા, જેણે વૈશ્વિક નાગરિક અધિકાર ચળવળોને મૂળભૂત રીતે બદલી નાખી. આર્થિક રીતે, તે ગુજરાતના સિમેન્ટ ઉદ્યોગ અને દરિયાઇ નિકાસ માટે એક નિર્ણાયક નોડ છે.",
  "1650": "તેની ચક્રવાતની નબળાઈને જોતાં, પોરબંદર મજબૂત દરિયાકાંઠાના આપત્તિ વ્યવસ્થાપન માળખા ધરાવે છે. માછીમાર સમુદાયો બદલાતા દરિયાઇ ઇકોસિસ્ટમ અને હવામાનની પેટર્નને અનુરૂપ, અંતર્ગત સ્થિતિસ્થાપકતા દર્શાવે છે.",
  "1672": "તેના જીવંત, ભોજન પ્રેમી લોકો માટે 'રંગીલા રાજકોટ' તરીકે ઓળખાય છે. સંસ્કૃતિ ઉત્સાહી નવરાત્રિની ઉજવણીઓ, ચાંદીના દાગીના બનાવવાની સમૃદ્ધ પરંપરા અને શાસ્ત્રીય કાઠિયાવાડી સાહિત્ય અને કળા દ્વારા ચિહ્નિત થયેલ છે.",
  "1676": "આલ્ફ્રેડ હાઇસ્કૂલમાં મહાત્મા ગાંધીના શાળાકીય શિક્ષણ સાથે ઊંડાણપૂર્વક સંકળાયેલ છે. આ જિલ્લો સૌરાષ્ટ્ર યુનિવર્સિટીનું ઘર છે, જે આ પ્રદેશમાં સંશોધન અને શિક્ષણને આગળ ધપાવતી એક મહત્વપૂર્ણ શૈક્ષણિક સંસ્થા છે.",
  "1680": "ભવિષ્યની પ્રાથમિકતાઓમાં તેના ઉત્પાદન આધારને સ્માર્ટ એન્જિનિયરિંગ અને ઇવીમાં સંક્રમિત કરવું, લાંબા ગાળાની પાણીની ટકાઉપણું ઉકેલવી, અને પશ્ચિમ ભારતમાં પ્રીમિયર મેડિકલ અને શૈક્ષણિક હબ તરીકે પોતાને સ્થાપિત કરવાનો સમાવેશ થાય છે.",
  "1704": "ઐતિહાસિક રીતે, સુરત પર્શિયન ગલ્ફ, યુરોપ અને દક્ષિણપૂર્વ એશિયા માટે ભારતની સૌથી મહત્વપૂર્ણ દરિયાઇ કડી હતી, જે હજ યાત્રીઓ (બાબ-અલ-મક્કા) માટે પ્રસ્થાન બિંદુ તરીકે અને બ્રિટિશ ઇસ્ટ ઇન્ડિયા કંપનીના પ્રથમ મુખ્યાલય તરીકે સેવા આપતી હતી.",
  "1708": "તાપી નદીના કિનારે જ્યાં તે અરબી સમુદ્ર સાથે મળે છે ત્યાં આવેલું છે. નીચાણવાળા નદીમુખની ભૂગોળ તેને ભરતીના પૂર અને અત્યંત વરસાદની ઘટનાઓ માટે અત્યંત સંવેદનશીલ બનાવે છે.",
  "1712": "ત્રિનેત્રેશ્વર મહાદેવ મંદિર ·",
  "1726": "ઘણીવાર 'સૌરાષ્ટ્રનું પ્રવેશદ્વાર' કહેવામાં આવે છે, સુરેન્દ્રનગર તેના વિસ્તૃત અર્ધ-શુષ્ક લેન્ડસ્કેપ્સ, કચ્છના નાના રણની અનન્ય ઇકોલોજી અને કપાસ અને મીઠાના મજબૂત ઉત્પાદન દ્વારા વર્ગીકૃત થયેલ છે.",
  "1730": "અર્થતંત્ર મોટા પાયે મીઠાના ઉત્પાદન (ભારતના અંતર્દેશીય મીઠાનો નોંધપાત્ર હિસ્સો પૂરો પાડે છે), ઉચ્ચ ગુણવત્તાની 'કલ્યાણ' કપાસની ખેતી, અને થાનગઢ સિરામિક્સ અને સેનિટરીવેર ઉદ્યોગ પર આધારિત છે.",
  "1734": "વિકાસ નર્મદા કેનાલ નેટવર્ક (સૌરાષ્ટ્ર બ્રાન્ચ કેનાલ) સાથે ભારે જોડાયેલો છે, જેણે સ્થાનિક ખેતીમાં ક્રાંતિ લાવી છે. સિરામિક ક્લસ્ટરો અને સૌર ઉર્જા ઉત્પાદન આસપાસ ઈન્ફ્રાસ્ટ્રક્ચર વિસ્તરી રહ્યું છે.",
  "1752": "તાપીમાં વારસો સ્મારક સ્થાપત્યને બદલે મૌખિક પરંપરાઓ અને આદિવાસી લોકકથાઓમાં ઊંડે ઉતરેલો છે. ગાયકવાડ દ્વારા બાંધવામાં આવેલ સોનગઢ કિલ્લા જેવા ઐતિહાસિક કિલ્લાઓ તેના વ્યૂહાત્મક લશ્કરી ભૂતકાળને પ્રકાશિત કરે છે.",
  "1756": "તાપીનું પ્રાથમિક યોગદાન દક્ષિણ ગુજરાતના વિશાળ કૃષિ અને ઔદ્યોગિક ક્ષેત્રો માટે જળ અને ઉર્જા જળાશય તરીકે સેવા આપવાનું છે, જ્યારે રાજ્યના સૌથી અધિકૃત આદિવાસી ઇકોલોજીકલ વિસ્તારોમાંથી એકને સાચવી રાખે છે.",
  "1760": "આદિવાસી સમુદાયોના જંગલ ઇકોસિસ્ટમ સાથેના ટકાઉ સહઅસ્તિત્વમાં અને વિશાળ ઉકાઈ ડેમ અને કાકરાપાર પરમાણુ સુવિધાની કામગીરી અંગે જિલ્લાના મજબૂત આપત્તિ વ્યવસ્થાપન પ્રોટોકોલમાં સ્થિતિસ્થાપકતા જોવા મળે છે.",
  "1781": "બરોડા રાજ્યની રાજધાની તરીકે, તેના સમગ્ર ભારતમાં ઊંડા રાજકીય અને સાંસ્કૃતિક જોડાણો હતા, જે મહારાષ્ટ્ર, બંગાળ અને તેનાથી આગળના કલાકારો, વિદ્વાનો અને સામાજિક સુધારકોને ભારે આશ્રય આપતા હતા.",
  "1784": "મહારાજા સયાજીરાવ ગાયકવાડ ત્રીજાએ શહેરનું ઊંડાણપૂર્વક આધુનિકીકરણ કર્યું. શ્રી અરવિંદો અને ડો. બી. આર. આંબેડકરે રચનાત્મક વર્ષો અહીં વિતાવ્યા હતા. મહારાજા સયાજીરાવ યુનિવર્સિટી (MSU) ઉચ્ચ શિક્ષણની અગ્રણી, ઐતિહાસિક સંસ્થા છે.",
  "1788": "ભાવિ વિઝન વિશ્વામિત્રી ઇકોસિસ્ટમને પુનઃસ્થાપિત કરવા, પ્રીમિયર શૈક્ષણિક અને જ્ઞાન હબ તરીકે તેની ભૂમિકાને વિસ્તારવા અને ગ્રીન મેન્યુફેક્ચરિંગ અને હાઇ-સ્પીડ ટ્રાન્ઝિટની આગામી પેઢીને એન્કર કરવા પર ધ્યાન કેન્દ્રિત કરે છે.",
  "1806": "ઐતિહાસિક રીતે, વલસાડના બંદરોએ યુરોપિયન સત્તાઓ સાથેના વેપારને સુવિધા આપી. ઉદવાડા વૈશ્વિક ઝોરાસ્ટ્રિયન ડાયસ્પોરાને ભારતમાં તેમના પ્રારંભિક મૂળ સાથે જોડતું આધ્યાત્મિક કેન્દ્ર છે.",
  "1810": "એક સુંદર દરિયાકાંઠો, ફળદ્રુપ મેદાનો અને પૂર્વમાં પશ્ચિમ ઘાટના ભારે જંગલવાળા, અસમાન ભૂપ્રદેશ દ્વારા વર્ગીકૃત થયેલ છે. તે ગુજરાતમાં સૌથી વધુ વરસાદ મેળવે છે. દમણ ગંગા નદીમાં ઔદ્યોગિક પ્રદૂષણ એક ગંભીર પડકાર છે.",
  "1830": "સંસ્કૃતિ પશુપાલક સમુદાયો, વાઇબ્રન્ટ ગ્રામીણ મેળાઓ અને સમૃદ્ધ લોક સંગીત દ્વારા વ્યાખ્યાયિત કરવામાં આવે છે. આ જિલ્લો એક કઠોર સરહદી જીવનશૈલીની ઉજવણી કરે છે, તેની બોલી અને પોશાકમાં પાડોશી રાજસ્થાનના ઊંડા પ્રભાવ સાથે.",
  "1834": "આ જિલ્લો તેના સ્થિતિસ્થાપક ખેડૂતો, સરહદ સુરક્ષા કર્મચારીઓ અને પશુપાલક જાતિઓ (માલધારી) દ્વારા વ્યાખ્યાયિત થયેલ છે. તાજેતરના વહીવટી ઉન્નતીકરણનો હેતુ વધુ સારી જાહેર સેવા વિતરણ માટે સ્થાનિક શાસન સંસ્થાઓ બનાવવાનો છે.",
  "1838": "વાવ-થરાદ માટે ભાવિ વિઝન મજબૂત વહીવટી માળખાગત સુવિધાઓ સ્થાપિત કરવા, ટકાઉ પાણીના ઉપયોગ દ્વારા કૃષિ ઉત્પાદનને મહત્તમ કરવા અને સરહદી અને રણ પર્યટન અર્થતંત્રો વિકસાવવા પર કેન્દ્રિત છે.",
  "1862": "ઐતિહાસિક રીતે, સાબરકાંઠામાં અરવલ્લીની ટેકરીઓમાંથી પસાર થતા રસ્તાઓ રાજસ્થાનના મેવાડ અને મારવાડ રાજ્યો સાથે ગુજરાતના મેદાનોને જોડતા મહત્વપૂર્ણ વેપાર અને લશ્કરી કોરિડોર તરીકે કામ કરતા હતા.",
  "1864": "ડેરી સહકારી મંડળીઓ દ્વારા વ્યાપક રોજગારીનું નિર્માણ કરીને સાબરકાંઠા ગુજરાતમાં શ્વેત ક્રાંતિનો આધારસ્તંભ રહ્યો છે. પોલો ફેસ્ટિવલે જિલ્લાને રાષ્ટ્રીય ઇકો-ટૂરિઝમ અને હેરિટેજ નકશા પર મૂક્યો છે.",
  "1868": "સહકારી ડેરી મોડેલ પાક નિષ્ફળતા સામે ખેડૂતો માટે ઊંડી આર્થિક સ્થિતિસ્થાપકતા પૂરી પાડે છે. નાજુક અરવલ્લી ઇકોસિસ્ટમને બચાવવા માટે આ જિલ્લો સમુદાય-આધારિત વન સંરક્ષણમાં પણ સંકળાયેલો છે.",
  "1882": "નર્મદા, જળ સંપત્તિ, પાણી પુરવઠા અને કલ્પસર વિભાગ.",
  "1888": "આ પૂરા પાડવામાં આવેલ પ્રોજેક્ટની ઝાંખી છે, ચકાસાયેલ વર્તમાન કામગીરી અહેવાલ નથી. આ એન્ટ્રી માટે રિપોર્ટિંગ તારીખો, ખર્ચ અને જિલ્લા-સ્તરના પરિણામના પુરાવા હજુ પૂરા પાડવામાં આવ્યા નથી.",
  "1897": "ખેડૂતોને આધુનિક કૃષિ પદ્ધતિઓ, ટેકનોલોજી અને જમીનની તંદુરસ્તીની માહિતીથી સશક્ત બનાવો.",
  "1901": "સમગ્ર ગુજરાતમાં લાખો ખેડૂતો.",
  "1902": "૨૦૦૦ ના દાયકા દરમિયાન ગુજરાતમાં સતત બે આંકડાનો કૃષિ વિકાસ દર.",
  "1907": "બેંકિંગ સંવાદદાતાઓ (બેંક મિત્રો) નો ઉપયોગ કરીને મોટા પાયે રાષ્ટ્રવ્યાપી નોંધણી શિબિરો.",
  "1911": "કલ્યાણકારી વિતરણ માટે જિલ્લા સ્તરે રાષ્ટ્રવ્યાપી સંકલન.",
  "1914": "શૌચાલયના નિર્માણ અને ઘન કચરા વ્યવસ્થાપન માટે સબસિડી સાથે વર્તન પરિવર્તન ઝુંબેશ.",
  "1918": "ગ્રામીણ ભારતને ખુલ્લામાં શૌચમુક્ત (ODF) જાહેર કરવું અને જાહેર આરોગ્ય સૂચકાંકોમાં નોંધપાત્ર સુધારો.",
  "1924": "આરોગ્ય અને પરિવાર કલ્યાણ વિભાગ, ગુજરાત સરકાર.",
  "1926": "ગુજરાતમાં MMR અને IMRમાં ભારે ઘટાડો, અને સંસ્થાકીય ડિલિવરીમાં નોંધપાત્ર વધારો.",
  "1931": "શૈક્ષણિક કિટનું વિતરણ, નવા વિદ્યાર્થીઓ માટે ઉત્સવનું વાતાવરણ ઊભું કરવું અને 'વિદ્યા નિધિ' દાન એકત્ર કરવું.",
  "1937": "ગ્રામ્ય કક્ષાએ નાગરિક સેવાઓ પૂરી પાડવા માટે તમામ ગ્રામ પંચાયતોને બ્રોડબેન્ડ સાથે જોડો.",
  "1941": "પ્રમાણપત્રો, જમીનના રેકોર્ડ અને બિલ ચુકવણી સેવાઓ માંગતા ગ્રામીણ નાગરિકો.",
  "1945": "ગુજરાતને ભારતમાં મુખ્ય રોકાણ ગંતવ્ય અને વૈશ્વિક વ્યાપાર કેન્દ્ર તરીકે સ્થાન આપવું.",
  "1949": "બેરોજગાર યુવાનો, ઔદ્યોગિક ક્ષેત્રો, MSMEs અને સમગ્ર રાજ્યનું અર્થતંત્ર.",
  "1952": "MoU ને વાસ્તવિક જમીન રોકાણો, પર્યાવરણીય ચિંતાઓ અને સંતુલિત પ્રાદેશિક વિકાસમાં રૂપાંતરિત કરવું.",
  "1957": "રાષ્ટ્રીય ખાદ્ય સુરક્ષા કાયદા (NFSA) હેઠળ ૮૦ કરોડથી વધુ લાભાર્થીઓને આવરી લેવામાં આવ્યા છે.",
  "1961": "વસ્તીના તળિયાના ૪૦% લોકોને સુલભ આરોગ્યસંભાળ પૂરી પાડીને સાર્વત્રિક આરોગ્ય કવરેજ પ્રાપ્ત કરો.",
  "1965": "સામાજિક-આર્થિક જાતિ વસ્તી ગણતરી દ્વારા ૫૦ કરોડથી વધુ સંવેદનશીલ નાગરિકોની ઓળખ કરવામાં આવી છે.",
  "1969": "તમામ લાયક પરિવારોને મૂળભૂત સુવિધાઓ સાથેનું કાયમી મકાન પૂરું પાડીને 'સૌના માટે ઘર'.",
  "1973": "બેઘર વ્યક્તિઓ અને અપૂરતા ઘરોમાં રહેતા લોકો, જેની માલિકી મુખ્યત્વે મહિલાઓના નામે છે.",
  "1977": "૨૦૨૪ સુધીમાં દરેક ગ્રામીણ ઘરને કાર્યરત ઘરગથ્થુ નળ જોડાણો પૂરા પાડવા.",
  "1981": "ગ્રામીણ પરિવારો, ખાસ કરીને મહિલાઓ અને છોકરીઓ જેઓ અગાઉ અંતરથી પાણી લાવતી હતી.",
  "1985": "શહેરી જેવી સુવિધાઓ પર ધ્યાન કેન્દ્રિત કરીને ગ્રામીણ સામુદાયિક જીવનને સાચવતા ગામોના ક્લસ્ટરો વિકસાવો.",
  "1990": "ગ્રામીણ-શહેરી વિભાજનને દૂર કરતા રાષ્ટ્રવ્યાપી ૩૦૦ રૂર્બન ક્લસ્ટરોનું નિર્માણ.",
  "1997": "શાસ્ત્રીય અને પ્રારંભિક મધ્યયુગીન",
  "1999": "વસાહતી ગુજરાત અને આધુનિક જાહેર જીવન",
  "2008": "એક કિલ્લેબંધીવાળી હડપ્પન વસાહત જે ઉપખંડમાં ઘોડાના અવશેષોના કેટલાક પ્રારંભિક અહેવાલ પુરાવા પ્રદાન કરવા માટે નોંધપાત્ર છે, જોકે આ શૈક્ષણિક રીતે ચર્ચાસ્પદ રહે છે.",
  "2015": "એક પ્રાચીન રાજધાની અને મુખ્ય ધાર્મિક કેન્દ્ર. ગિરનાર પર્વત વિસ્તાર સદીઓ સુધી ફેલાયેલા નોંધપાત્ર ખડક શિલાલેખો ધરાવે છે, જે વહીવટી, ધાર્મિક અને જાહેર બાંધકામોના ઇતિહાસની વિગતો આપે છે."
}

